CREATE TEMP TABLE lesson_ledger_payments (
  payment_id BIGINT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status = 'succeeded')
);
INSERT INTO pg_temp.lesson_ledger_payments VALUES (5001,'succeeded'), (5002,'succeeded');
CREATE TEMP TABLE lesson_ledger_entries (
  entry_id BIGINT PRIMARY KEY,
  payment_id BIGINT NOT NULL REFERENCES pg_temp.lesson_ledger_payments(payment_id),
  account_id BIGINT NOT NULL,
  side TEXT NOT NULL CHECK (side IN ('debit','credit')),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0)
);
INSERT INTO pg_temp.lesson_ledger_entries VALUES
