CREATE TEMP TABLE lesson_mutable_balances (
  account_id BIGINT PRIMARY KEY,
  opening_balance NUMERIC(12,2) NOT NULL,
  current_balance NUMERIC(12,2) NOT NULL
);
INSERT INTO pg_temp.lesson_mutable_balances VALUES (1,100000.00,55000.00), (2,50000.00,95000.00);

